CREATE TABLE IF NOT EXISTS "product" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "slug" VARCHAR(255) NOT NULL UNIQUE,
    "name" VARCHAR(255) NOT NULL,
    "description" TEXT,
    "price" DECIMAL(10, 2) NOT NULL CHECK ("price" >= 0),
    "active" BOOLEAN NOT NULL,
    "stock" INTEGER CHECK ("stock" >= 0),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "product_image" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "product_id" INTEGER NOT NULL,
    "position" INTEGER,
    "link" VARCHAR(255) NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TYPE order_status AS ENUM ('en attente', 'payée', 'traitée');

CREATE TABLE IF NOT EXISTS "order" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "email" VARCHAR(255) NOT NULL,
    "address" VARCHAR(255) NOT NULL,
    "city" VARCHAR(255) NOT NULL,
    "zip" VARCHAR(10) NOT NULL,
    "ref" INTEGER NOT NULL,
    "date" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "total" DECIMAL(10, 2) NOT NULL CHECK ("total" >= 0),
    "status" order_status NOT NULL DEFAULT 'en attente',
    "shipping_offer_name" VARCHAR(255) NOT NULL,
    "shipping_offer_price" DECIMAL(10, 2) NOT NULL CHECK ("shipping_offer_price" >= 0),
    "shipping_company" VARCHAR(255),
    "shipping_cost" DECIMAL(10, 2) CHECK ("shipping_cost" >= 0),
    "tracking_number" VARCHAR(255),
    "access_key" UUID NOT NULL DEFAULT gen_random_uuid (),
    PRIMARY KEY ("id"),
    CONSTRAINT order_ref_unique UNIQUE ("ref")
);

CREATE TABLE IF NOT EXISTS "order_product" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" INTEGER NOT NULL,
    "product_id" INTEGER NOT NULL,
    "quantity" INTEGER NOT NULL CHECK ("quantity" > 0),
    "paid_price" DECIMAL(10, 2) NOT NULL CHECK ("paid_price" >= 0),
    PRIMARY KEY ("id")
);

CREATE TYPE payment_status AS ENUM ('en attente', 'réussi', 'échoué');

CREATE TABLE IF NOT EXISTS "payment" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" INTEGER NOT NULL,
    "stripe_ref" VARCHAR(255) NOT NULL,
    "amount" DECIMAL(10, 2) NOT NULL CHECK ("amount" >= 0),
    "currency" VARCHAR(255) NOT NULL,
    "status" payment_status NOT NULL DEFAULT 'en attente',
    "stripe_event_id" VARCHAR(255) UNIQUE,
    PRIMARY KEY ("id"),
    CONSTRAINT payment_order_id_unique UNIQUE ("order_id")
);

CREATE TABLE IF NOT EXISTS "shipping_offer" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL UNIQUE,
    "price" DECIMAL(10, 2) NOT NULL CHECK ("price" >= 0),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "shipping_company" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL UNIQUE,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "shipping_company_offer" (
    "company_id" INTEGER NOT NULL,
    "offer_id" INTEGER NOT NULL,
    "cost" DECIMAL(10, 2) NOT NULL CHECK ("cost" >= 0),
    PRIMARY KEY ("company_id", "offer_id")
);

ALTER TABLE "product" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "product_image" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "order" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "order_product" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "payment" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "shipping_offer" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "shipping_company" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "shipping_company_offer" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "product_image"
ADD FOREIGN KEY ("product_id") REFERENCES "product" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "order_product"
ADD FOREIGN KEY ("order_id") REFERENCES "order" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "order_product"
ADD FOREIGN KEY ("product_id") REFERENCES "product" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "payment"
ADD FOREIGN KEY ("order_id") REFERENCES "order" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "shipping_company_offer"
ADD FOREIGN KEY ("company_id") REFERENCES "shipping_company" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "shipping_company_offer"
ADD FOREIGN KEY ("offer_id") REFERENCES "shipping_offer" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;